// ValidateURL is exported so shared definitions get the same rules.
func ValidateURL(raw string) error {
	if err := validateURL(raw); err != nil {
		return err
	}
	if hasURLCredential(raw) {
		return fmt.Errorf("%w: invalid url: must not carry a password or token; use a git_token credential", ErrInvalidInput)
	}
	return nil
}

// hasURLCredential reports userinfo that can hold a secret: any https
// userinfo, and a password in ssh:// or scp-style addresses.
func hasURLCredential(raw string) bool {
	if strings.HasPrefix(raw, "https://") {
		u, err := neturl.Parse(raw)
		return err != nil || u.User != nil
	}
	if rest, ok := strings.CutPrefix(raw, "ssh://"); ok {
		authority, _, _ := strings.Cut(rest, "/")
		if i := strings.LastIndex(authority, "@"); i >= 0 {
			return strings.Contains(authority[:i], ":")
		}
		return false
	}
	if i := strings.Index(raw, "@"); i >= 0 {
		return strings.Contains(raw[:i], ":")
	}
	return false
}
