// Encode renders r as JSON of at most maxBytes. A report too large keeps
// the most playbooks from the front that fit. No marshal ever builds more
// than maxBytes plus one playbook plus the report's own (bounded) fields.
func Encode(r Report, maxBytes int) ([]byte, Report, error) {
	// How many playbooks from the front can fit at all, one playbook
	// marshalled at a time (one playbook is bounded by its walk caps).
	fit, total := 0, 0
	for _, pb := range r.Playbooks {
		b, err := json.Marshal(pb)
		if err != nil {
			return nil, r, fmt.Errorf("encode variable sources: %w", err)
		}
		if total += len(b) + 1; total > maxBytes {
			break
		}
		fit++
	}
	if fit == len(r.Playbooks) {
		data, err := json.Marshal(r) // bounded: every playbook fits
		if err != nil {
			return nil, r, fmt.Errorf("encode variable sources: %w", err)
		}
		if len(data) <= maxBytes {
			return data, r, nil
		}
	}
	// Search only among cuts that can fit, so each marshal stays bounded.
	lo, hi := 0, min(fit, len(r.Playbooks)-1)
	var best []byte
	var bestReport Report
	for lo <= hi {
		keep := (lo + hi) / 2
		cut := dropPlaybooks(r, keep, maxBytes)
		data, err := json.Marshal(cut)
		if err != nil {
			return nil, r, fmt.Errorf("encode variable sources: %w", err)
		}
		if len(data) <= maxBytes {
			best, bestReport, lo = data, cut, keep+1
		} else {
			hi = keep - 1
		}
	}
	if best == nil {
		return nil, r, fmt.Errorf("encode variable sources: the report does not fit %d bytes even without playbooks", maxBytes)
	}
	return best, bestReport, nil
}

