// pythonQuote is urllib.parse.quote(v, safe): every byte except ASCII
// letters, digits, "_.-~" and safe written as %XX (upper-case hex).
func pythonQuote(v, safe string) string {
	var sb strings.Builder
	for _, c := range []byte(v) {
		if c < 0x80 && (unicode.IsLetter(rune(c)) || unicode.IsDigit(rune(c)) || strings.IndexByte("_.-~"+safe, c) >= 0) {
			sb.WriteByte(c)
		} else {
			fmt.Fprintf(&sb, "%%%02X", c)
		}
	}
	return sb.String()
}

